const mails = await api.get('/mails', { label: 'complaint' });
const customerIds = mails.items.map(m => m.customer_id).filter(id => id);
const uniqueIds = [...new Set(customerIds)];
const tiers = {};
for (const id of uniqueIds) {
  const cust = await api.get(`/customers/${id}`);
  tiers[id] = cust.tier;
}
return { tiers };

